// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

export const rippleButtonVariantValues = ["primary", "secondary", "ghost", "danger"] as const;
export const rippleButtonSizeValues = ["sm", "md", "lg"] as const;

/** A button that sends a ripple out from where you pressed it, or from its centre when pressed with the keyboard. Builds on Button. */
export interface RippleButtonSpecProps {
  /**
   * Button label. Icon-only buttons must pass aria-label instead.
   */
  children: ReactNode;
  /**
   * Visual emphasis, as on Button.
   * @default "primary"
   */
  variant?: "primary" | "secondary" | "ghost" | "danger";
  /**
   * Height, padding and font size, as on Button.
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Milliseconds the ripple takes to spread and fade.
   * @default 600
   */
  duration?: number;
  /**
   * Prevents interaction and dims the button.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Shows a spinner and blocks presses; the pending state is announced.
   * @default false
   */
  isLoading?: boolean;
  /**
   * Called when the button is pressed by mouse, touch or keyboard.
   */
  onPress?: () => void;
}

export const rippleButtonDefaults = {
  variant: "primary",
  size: "md",
  duration: 600,
  isDisabled: false,
  isLoading: false,
} as const;

export const rippleButtonMeta = {
  "name": "RippleButton",
  "version": "0.1.0",
  "status": "experimental",
  "role": "button"
} as const;
